## Submitted testbench
```systemverilog
module tb;

  // -------------------------------------------------
  // Parameters
  // -------------------------------------------------
  localparam int CLK_PERIOD = 8;          // 125 MHz
  localparam int BIT_CLOCKS = 40;         // prescale = 5 → 5*8 = 40

  // -------------------------------------------------
  // Clock generation
  // -------------------------------------------------
  reg clk = 0;
  initial begin
    forever #(CLK_PERIOD/2) clk = ~clk;
  end

  // -------------------------------------------------
  // Reset (active‑high)
  // -------------------------------------------------
  reg rst = 1;

  // -------------------------------------------------
  // Prescale value (must be non‑zero when required)
  // -------------------------------------------------
  wire [15:0] prescale_val = 16'd5;       // constant non‑zero

  // -------------------------------------------------
  // UART_RX interface signals
  // -------------------------------------------------
  logic rxd;
  logic [7:0] m_axis_tdata;
  logic m_axis_tvalid;
  logic m_axis_tready;
  logic busy;
  logic overrun_error;
  logic frame_error;

  // -------------------------------------------------
  // AXI‑Stream tready is permanently high (receiver always ready)
  // -------------------------------------------------
  initial begin
    m_axis_tready = 1'b1;
  end

  // -------------------------------------------------
  // Connect constant prescale to the DUT
  // -------------------------------------------------
  assign prescale_val = 16'd5;

  // -------------------------------------------------
  // Instantiate the RX module (coverage is bound to this instance)
  // -------------------------------------------------
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd          (rxd),
    .busy         (busy),
    .overrun_error(overrun_error),
    .frame_error  (frame_error),
    .prescale     (prescale_val)
  );

  // -------------------------------------------------
  // Helper task: wait for N negative‑edge clock cycles
  // -------------------------------------------------
  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  // -------------------------------------------------
  // Task: transmit a complete UART frame on rxd
  //   stop_low = 1'b1 forces a low stop bit → frame_error is generated
  // -------------------------------------------------
  task automatic send_frame(input byte unsigned data, input logic stop_low);
    begin
      // START bit
      rxd = 1'b0;
      wait_clks(BIT_CLOCKS);
      // Data bits, LSB first
      for (int i = 0; i < 8; i++) begin
        rxd = data[i];
        wait_clks(BIT_CLOCKS);
      end
      // STOP bit
      if (stop_low) rxd = 1'b0; else rxd = 1'b1;
      wait_clks(BIT_CLOCKS);
      // Return to idle
      rxd = 1'b1;
    end
  endtask

  // -------------------------------------------------
  // Main stimulus
  // -------------------------------------------------
  initial begin
    // Stabilise clock
    # (CLK_PERIOD*2);
    // De‑assert reset
    rst = 1;
    wait_clks(2);
    rst = 0;
    wait_clks(2);
    // Ensure we are past reset
    repeat (5) @(negedge clk);

    // Idle state on rxd
    rxd = 1'b1;

    // -------------------------------------------------
    // 1) Generate a frame error (stop bit low)
    // -------------------------------------------------
    send_frame(8'h00, 1'b1);
    // Allow frame_error to be set and stabilised
    repeat (12) @(negedge clk);

    // -------------------------------------------------
    // 2) Send the word 0x3C with a proper (high) stop bit.
    //    This frame is accepted while the previous frame_error
    //    is still high, satisfying the $past(frame_error) condition.
    // -------------------------------------------------
    send_frame(8'h3C, 1'b0);
    // Wait long enough for the handshake to complete,
    // tvalid to drop, and for the cover property to be evaluated.
    repeat (30) @(negedge clk);

    // If we reach here the target coverage point has been hit.
    $display("TESTBENCH COMPLETED");
    $finish;
  end

endmodule
```

